head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf05600";
scwin.delay = false;
scwin.result = undefined;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":1
        ,"mmenu":6
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf05600' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf05600.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_chgpass_onblur
 * @description ipt_chgpass 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_chgpass_onblur = async function(e){
    try {
        await scwin.fnKISAPwCheck()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05600.ipt_chgpass_onblur' }); }
};

/**
 * @method
 * @name btn_passchk_onclick
 * @description btn_passchk 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_passchk_onclick = async function(e){
    try {
        await scwin.passchk()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05600.btn_passchk_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSavePassword
 * @description fn Save Password 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSavePassword = async function () {
    const sbmOptions = {
        id: "tx_fnSavePassword",
        method: "post",
        action: "/account/userPw.do",
        ref: "dma_fnSavePasswordReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_test
 * @description test 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_test = async function () {
    const sbmOptions = {
        id: "tx_test",
        method: "post",
        action: "/account/userPw.do",
        ref: "dma_testReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnKISAPwCheck
 * @description fn KISAPw Check 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnKISAPwCheck = async function () {
    const sbmOptions = {
        id: "tx_fnKISAPwCheck",
        method: "post",
        action: "/common/common.do",
        ref: "dma_fnKISAPwCheckReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkPwd
 * @description check Pwd 처리
 * @param {*} aObj aObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPwd = async function (aObj) {
    const pwVal = aObj.getValue();
    if (pwVal.length < 9) {
        await $c.win.alert("변경 비밀번호를 9자 이상 입력하셔야 합니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const strChk = /^[\A-Za-z0-9_!@#^&*()]{8,}$/;
    if (!(strChk.test(pwVal))) {
        await $c.win.alert("변경 비밀번호는 한글,띄어쓰기는 사용 할 수 없습니다.\n_!@#^&*() 이외의 특수문자는 사용 할 수 없습니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const strIsurCd = $c.util.getComponent('ipt_isurCd').getValue();
    if (pwVal.indexOf(strIsurCd) !== -1) {
        await $c.win.alert("개인정보가 포함된 비밀번호는 사용하실 수 없습니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const alpha_t = "abcdefghijklmnopqrstuvwxyz";
    const alpha_big_t = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const sChar_t = "_!@#^&*()";
    const number_t = "1234567890";
    let sChar_Count_t = 0;
    let alphaCheck_t = false;
    let alphaBicCheck_t = false;
    let numberCheck_t = false;
    for (let i = 0; i < pwVal.length; i++) {
        if (sChar_t.indexOf(pwVal.charAt(i)) !== -1) {
            sChar_Count_t++;
        }
        if (alpha_t.indexOf(pwVal.charAt(i)) !== -1) {
            alphaCheck_t = true;
        }
        if (alpha_big_t.indexOf(pwVal.charAt(i)) !== -1) {
            alphaBicCheck_t = true;
        }
        if (number_t.indexOf(pwVal.charAt(i)) !== -1) {
            numberCheck_t = true;
        }
    }
    if ((sChar_Count_t < 1 || alphaCheck_t !== true || numberCheck_t !== true) && (sChar_Count_t < 1 || alphaBicCheck_t !== true || numberCheck_t !== true)) {
        await $c.win.alert("변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const charChk = /^[\a-z]{8,}$/;
    const numChk = /^[\d]{8,}$/;
    if (charChk.test(pwVal) || numChk.test(pwVal)) {
        await $c.win.alert('문자 또는 숫자만으로 구성된 변경 비밀번호는 사용하실 수 없습니다.');
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const keyboardWord = ["qwertyuiop", "poiuytrewq", "asdfghjkl", "lkjhgfdsa", "zxcvbnm", "mnbvcxz"];
    for (let i = 0; i < keyboardWord.length; i++) {
        for (let j = 0; j < keyboardWord[i].length; j++) {
            if (keyboardWord[i].substring(j, j + 4).length === 4) {
                if (!(pwVal.toLowerCase().indexOf(keyboardWord[i].substring(j, j + 4)) < 0)) {
                    await $c.win.alert('키보드상의 연속된 배열(' + keyboardWord[i].substring(j, j + 4) + ')로 구성된 변경 비밀번호는 사용하실 수 없습니다.');
                    (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
                    return false;
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name passchk
 * @description passchk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.passchk = async function () {
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_nowpass').getValue()) === 0) {
        await $c.win.alert("현재비밀번호를 입력하세요");
        $c.util.getComponent("ipt_nowpass").focus();
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_chgpass').getValue()) === 0) {
            await $c.win.alert("변경비밀번호를 입력하세요");
            $c.util.getComponent("ipt_chgpass").focus();
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_rechgpass').getValue()) === 0) {
                await $c.win.alert("변경비밀번호를 재 입력하세요");
                $c.util.getComponent("ipt_rechgpass").focus();
            } else {
                if (!await scwin.checkPwd($c.util.getComponent('ipt_chgpass'))) {
                    return;
                }
                if ($c.util.getComponent('ipt_chgpass').getValue()!== $c.util.getComponent('ipt_rechgpass').getValue()) {
                    await $c.win.alert("두개의 비밀번호가 일치하지 않습니다.");
                    $c.util.getComponent("ipt_chgpass").focus();
                    return;
                }
                if ($c.util.getComponent('dma_fnSavePasswordReq').get('sendLevel') === "C") {
                    await $c.win.alert("보안등급이 낮습니다. 비밀번호를 다시 입력해주십시오.");
                    $c.util.getComponent("ipt_chgpass").focus();
                    return;
                }
                if (await $c.win.confirm("변경하시겠습니까?")) {
                    await scwin.fnSavePassword();
                }
            }
        }
    }
};

/**
 * @method
 * @name fnNowPwCheck
 * @description fn Now Pw Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnNowPwCheck = function () {
    const base_url = "";
    let action_path = "";
    action_path = "/account/userPw.do";
    const fm = (document.SendForm || { elements: [] });
    const aes_nowpass = scwin.aES256($c.util.getComponent('ipt_nowpass').getValue());
    const aes_chgpass = scwin.aES256($c.util.getComponent('ipt_chgpass').getValue());
    const aes_rechgpass = scwin.aES256($c.util.getComponent('ipt_rechgpass').getValue());
    const pwBackupfm = (document.PwBackupForm || { elements: [] });
    $c.util.getComponent('dma_fnSavePasswordReq').set('backupNowPass', $c.util.getComponent('ipt_nowpass').getValue());
    $c.util.getComponent('dma_fnSavePasswordReq').set('backupChgPass', $c.util.getComponent('ipt_chgpass').getValue());
    $c.util.getComponent('dma_fnSavePasswordReq').set('backupReChgPass', $c.util.getComponent('ipt_rechgpass').getValue());
    $c.util.getComponent("ipt_nowpass").setValue(aes_nowpass);
    $c.util.getComponent("ipt_chgpass").setValue(aes_chgpass);
    $c.util.getComponent("ipt_rechgpass").setValue(aes_rechgpass);
    $("input[name='method']").val("checkNowPassword");
    $.ajax({ type: "POST", async: false, url: base_url + action_path, data: $("#SendForm").serialize(), success: function(data) {
                scwin.result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                $c.util.getComponent('ipt_temp').setValue(scwin.result.sendResult);
                $c.util.getComponent("ipt_nowpass").setValue($c.util.getComponent('dma_fnSavePasswordReq').get('backupNowPass'));
                $c.util.getComponent("ipt_chgpass").setValue($c.util.getComponent('dma_fnSavePasswordReq').get('backupChgPass'));
                $c.util.getComponent("ipt_rechgpass").setValue($c.util.getComponent('dma_fnSavePasswordReq').get('backupReChgPass'));
            }, error: async function(request, status, error) {
                await $c.win.alert("현재 패스워드를 조회 할 수 없습니다. 관리자에게 문의하십시오.");
                return;
            }, complete: function() {

            } });
};

/**
 * @method
 * @name fnSavePassword
 * @description fn Save Password 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSavePassword = async function () {
    const fm = (document.SendForm || { elements: [] });
    if ($c.util.getComponent('ipt_nowpass').getValue()=== $c.util.getComponent('ipt_chgpass').getValue()) {
        await $c.win.alert("현재 비밀번호와 동일한 비밀번호는 사용할 수 없습니다.");
        $c.util.getComponent("ipt_chgpass").focus();
        return;
    }
    $c.util.getComponent('dma_fnSavePasswordReq').set('method', "updatePassword");
    fm.action = "/account/userPw.do";
    fm.target = "_self";
    await scwin.tx_fnSavePassword();
};

/**
 * @method
 * @name test
 * @description test 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.test = async function () {
    const fm = (document.SendForm || { elements: [] });
    $c.util.getComponent('dma_fnSavePasswordReq').set('method', "updatePassword");
    fm.action = "/account/userPw.do";
    fm.target = "_self";
    await scwin.tx_test();
};

/**
 * @method
 * @name fnDelayKeyup
 * @description fn Delay Keyup 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnDelayKeyup = function () {
    if (!scwin.delay) {
        scwin.delay = true;
        self.setTimeout(async function(){ await scwin.fnKISAPwCheck() }, 1000);
    }
};

/**
 * @method
 * @name aES256
 * @description a ES256 처리
 * @param {*} message message
 * @returns {void}
 * @hidden N
 */
scwin.aES256 = function (message) {
    const key = CryptoJS.enc.Hex.parse('000102030405060708090a0b0c0d0e0f');
    const iv = CryptoJS.enc.Hex.parse('101112131415161718191a1b1c1d1e1f');
    const padMsg = scwin.padString(message);
    const encrypted = CryptoJS.AES.encrypt(padMsg, key, { iv: iv, padding: CryptoJS.pad.NoPadding, mode: CryptoJS.mode.CBC });
    return encrypted;
};

/**
 * @method
 * @name padString
 * @description pad String 처리
 * @param {*} source source
 * @returns {void}
 * @hidden N
 */
scwin.padString = function (source) {
    const paddingChar = ' ';
    const size = 16;
    const x = source.length % size;
    const padLength = size - x;
    for (let i = 0; i < padLength; i++) {
        source += paddingChar;
    }
    return source;
};

/**
 * @method
 * @name fnReset
 * @description fn Reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnReset = function () {
    (document.SendForm || { elements: [] }).reset();
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name fnKISAPwCheck_done
 * @description fn KISAPw Check done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnKISAPwCheck_done = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    jsReturn(scwin.result.sendResult, scwin.result.sendLevel);
    $c.util.getComponent("ipt_nowpass").setValue($c.util.getComponent('dma_fnSavePasswordReq').get('backupNowPass'));
    $c.util.getComponent("ipt_chgpass").setValue($c.util.getComponent('dma_fnSavePasswordReq').get('backupChgPass'));
    $c.util.getComponent("ipt_rechgpass").setValue($c.util.getComponent('dma_fnSavePasswordReq').get('backupReChgPass'));
};

/**
 * @method
 * @name fnKISAPwCheck
 * @description fn KISAPw Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnKISAPwCheck = async function () {
    const r = await scwin.tx_fnKISAPwCheck();
    try {
        scwin.fnKISAPwCheck_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body !== null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldinf05600.fnKISAPwCheck' });
    }
    return r;
};
